"""Built-in catalogue of published ontologies, vocabularies and data standards.

The builder never starts from a blank page: candidates are picked from this list by keyword match
(locally, no network), shown to the AI model with the domain and scope, and the model chooses what to
reuse and may add standards it knows that are missing here. The catalogue is reference data - links
and namespaces should still be verified by the ontologist before publishing (the UI says so).

Each entry: id, name, publisher, url, prefix, namespace ('' when the standard is not an RDF vocabulary),
kind (ontology | vocabulary | standard | upper), tags (matching keywords), description, terms (examples).
"""
import re


def _e(id, name, publisher, url, prefix, namespace, kind, tags, description, terms=""):
    return {"id": id, "name": name, "publisher": publisher, "url": url, "prefix": prefix, "namespace": namespace,
            "kind": kind, "tags": tags.split(), "description": description,
            "terms": [t.strip() for t in terms.split(",") if t.strip()]}


