BY_ID = {e["id"]: e for e in CATALOGUE}
GENERAL = ("schema", "skos", "prov", "time", "dcterms", "org")

_STOP = set("the a an of and or for to in on with by from at as is are be this that it its all any into our their "
            "management system systems data information process processes including include etc such using used".split())


def _stem(w: str) -> str:
    for suf in ("ies", "ing", "es", "s"):
        if len(w) > len(suf) + 2 and w.endswith(suf):
            return w[:-len(suf)] + ("y" if suf == "ies" else "")
    return w


def tokens(text: str) -> list[str]:
    return [_stem(w) for w in re.findall(r"[a-z][a-z0-9&-]+", (text or "").lower()) if w not in _STOP]


def candidates(domain: str, scope: str = "", notes: str = "", limit: int = 18) -> list[dict]:
    """Catalogue entries that match the domain/scope, best first; general-purpose vocabularies are always offered."""
    words = tokens(f"{domain} {domain} {scope} {notes[:2000]}")      # the domain counts double
    counts: dict[str, int] = {}
    for w in words:
        counts[w] = counts.get(w, 0) + 1
    scored = []
    for e in CATALOGUE:
        tags = {_stem(t) for t in e["tags"]} | set(tokens(e["name"]))
        score = sum(min(c, 3) for w, c in counts.items() if w in tags)
        if score or e["id"] in GENERAL:
            scored.append((score + (0.5 if e["id"] in GENERAL else 0), e))
    scored.sort(key=lambda x: -x[0])
    return [dict(e, match=round(s, 1)) for s, e in scored[:limit]]
